import * as T from './vendor/three.module.js';
export function buildShutter(w,g,d){const a=w.a,steel=a.get('metal',0x9a9b88),dark=a.plain(0x373e37),tag={id:'door',key:'loading'};g.position.set(d.x,0,d.z);g.userData.slats=[];for(let i=0;i<20;i++){const y=i*.14;const slat=w.box(0,y+.07,0,d.w-.10,.14,.07,steel,false,g,tag);slat.userData.base=y;w.box(0,.045,-.043,d.w-.15,.014,.018,dark,false,slat);g.userData.slats.push(slat);}for(const x of[-d.w/2,d.w/2])w.box(x,1.42,0,.10,2.84,.21,steel,false,g);w.box(0,2.99,0,d.w+.3,.36,.40,steel,false,g);w.box(0,.07,-.07,d.w-.05,.08,.10,dark,false,g,tag);g.userData.bottom=g.children.at(-1);for(const side of[-1,1]){const z=d.z+side*.23;w.box(d.x-d.w/2-.48,1.28,z,.26,.46,.09,dark);for(const[open,y,color]of[[true,1.39,0x4e7951],[false,1.16,0x8e4636]]){w.box(d.x-d.w/2-.48,y,z+side*.06,.13,.13,.035,a.plain(color),false,w.scene,{id:'loadingSwitch',key:open?'open':'close'});w.target('loadingSwitch',open?'open':'close',d.x-d.w/2-.48,y,z+side*.08,open?'升起卸货卷帘门':'降下卸货卷帘门');}const chain=new T.Group();w.scene.add(chain);chain.position.set(d.x-d.w/2-.80,1.5,z);for(let i=0;i<16;i++){const m=new T.Mesh(new T.TorusGeometry(.023,.006,4,7),steel);m.position.y=-i*.055;m.rotation.y=i%2?Math.PI/2:0;m.userData.target={id:'loadingChain'};chain.add(m);}w.target('loadingChain',null,chain.position.x,1.2,z,'应急手拉卷帘门');}
 for(const x of[-d.w/2-.07,d.w/2+.07])for(const y of[.80,1.35,1.90])w.box(x,y,-.18,.10,.24,.19,dark,false,g);}
export function syncShutter(g,s){const u=s.loadingLift??(s.doors.loading?1:0),lift=u*2.9;for(const m of g.userData.slats){const bottom=m.userData.base+lift,h=Math.min(.14,2.80-bottom);m.visible=h>0&&!s.loadingBroken;if(m.visible){m.position.y=bottom+h/2;m.scale.y=h/.14;}}g.userData.bottom.visible=u<.95&&!s.loadingBroken;g.userData.bottom.position.y=.07+lift;}
